  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "The power supply assembly whose components are replaced in these procedures.",
        "category": "power supply"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "A valve in the gas supply path, connected to gas supply hoses and the power board.",
        "category": "gas control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "The board with the J6 solenoid valve connector and the J12 TORCH START slot.",
        "category": "electrical"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "A barrier that is lifted to access the connector on the power board.",
        "category": "electrical enclosure"
      },
      {
        "component_id": "comp_center_panel",
        "name": "Center panel",
        "description": "A panel that holds the solenoid valve and provides wire routing notches and wire attachment studs.",
        "category": "structural"
      },
      {
        "component_id": "comp_gas_supply_hose",
        "name": "Gas supply hose",
        "description": "A hose connected to the solenoid valve and air filter assembly.",
        "category": "gas delivery"
      },
      {
        "component_id": "comp_torch_lead",
        "name": "Torch lead",
        "description": "The torch lead assembly, with electrical wires and a brass gas supply fitting, routed through the front panel.",
        "category": "torch connection"
      },
      {
        "component_id": "comp_torch_lead_cable",
        "name": "Torch lead cable",
        "description": "The cable portion of the torch lead, which can be replaced separately from the whole torch assembly.",
        "category": "torch connection"
      },
      {
        "component_id": "comp_strain_relief",
        "name": "Strain relief",
        "description": "The strain relief fitted to the torch lead at the front panel.",
        "category": "cable protection"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "The panel through which the torch lead and strain relief are installed.",
        "category": "structural"
      },
      {
        "component_id": "comp_air_filter_assembly",
        "name": "Air filter assembly",
        "description": "The assembly connected to the gas supply hose, copper heat exchange coil, and drain hose.",
        "category": "air filtration"
      },
      {
        "component_id": "comp_air_filter",
        "name": "Air filter",
        "description": "The filter installed in the power supply and connected to the gas supply hose and copper heat exchange coil.",
        "category": "air filtration"
      },
      {
        "component_id": "comp_air_filter_bowl",
        "name": "Air filter bowl",
        "description": "The bowl at the bottom of the air filter, with a fitting for the drain hose.",
        "category": "air filtration"
      },
      {
        "component_id": "comp_air_filter_element",
        "name": "Air filter element",
        "description": "The replaceable element of the air filter.",
        "category": "air filtration"
      },
      {
        "component_id": "comp_copper_heat_exchange_coil",
        "name": "Copper heat exchange coil",
        "description": "A coil connected to the left-side fitting of the air filter.",
        "category": "heat exchange"
      },
      {
        "component_id": "comp_drain_hose",
        "name": "Drain hose",
        "description": "A hose connected to the bottom of the air filter bowl and routed through the power supply base.",
        "category": "drainage"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan in the power supply; its wires are routed behind the air filter.",
        "category": "cooling"
      },
      {
        "component_id": "comp_fan_plenum",
        "name": "Fan plenum",
        "description": "A plenum attached to the fan casing that can be removed for access to the air filter.",
        "category": "cooling"
      }
    ],
